+/** WB-7: lays out JSON with two-space indents by changing whitespace only, so 803.40 stays 803.40. */
+function indent(raw: string): string {
+  const pad = (depth: number) => '  '.repeat(depth);
+  let out = '';
+  let depth = 0;
+  let inString = false;
+  let escaped = false;
+  for (let i = 0; i < raw.length; i += 1) {
+    const ch = raw[i] ?? '';
+    if (inString) {
+      out += ch;
+      if (escaped) escaped = false;
+      else if (ch === '\\') escaped = true;
+      else if (ch === '"') inString = false;
+    } else if (ch === '"') {
+      inString = true;
+      out += ch;
+    } else if (/\s/.test(ch)) {
+      continue;
+    } else if (ch === '{' || ch === '[') {
+      let next = i + 1;
+      while (next < raw.length && /\s/.test(raw[next] ?? '')) next += 1;
+      if (raw[next] === (ch === '{' ? '}' : ']')) {
+        out += ch + raw[next];
+        i = next;
+      } else {
+        depth += 1;
+        out += `${ch}\n${pad(depth)}`;
+      }
+    } else if (ch === '}' || ch === ']') {
+      depth -= 1;
+      out += `\n${pad(depth)}${ch}`;
+    } else if (ch === ',') {
+      out += `,\n${pad(depth)}`;
+    } else if (ch === ':') {
+      out += ': ';
+    } else {
+      out += ch;
+    }
+  }
+  return out;
+}
